//! paintfx.library's functions: Paint's effects and transforms, worked on
//! pixels in memory. It is Paint's own, in Paint's drawer, and Paint
//! opens it by its path (sdk.paintfx.PAINTFXPATH). A call that needs
//! memory answers 0, or ERROR_NO_FREE_STORE when there is none.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/paintfx_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const paintfx = @import("../libs/paintfx/paintfx.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "paintfx.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const AdjustColours = libraries.lvo(4);
    pub const BlurPixels = libraries.lvo(5);
    pub const SharpenPixels = libraries.lvo(6);
    pub const ScalePixels = libraries.lvo(7);
    pub const TransformPixels = libraries.lvo(8);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const AdjustColours = *const fn (*PaintFXBase, *const paintfx.Pixels, *const paintfx.Adjust) callconv(.c) void;
    pub const BlurPixels = *const fn (*PaintFXBase, *const paintfx.Pixels, *const paintfx.Pixels, u32) callconv(.c) i32;
    pub const SharpenPixels = *const fn (*PaintFXBase, *const paintfx.Pixels, *const paintfx.Pixels, u32, u32) callconv(.c) i32;
    pub const ScalePixels = *const fn (*PaintFXBase, *const paintfx.Pixels, *const paintfx.Pixels, u32) callconv(.c) i32;
    pub const TransformPixels = *const fn (*PaintFXBase, *const paintfx.Pixels, *const paintfx.Pixels, *const paintfx.Matrix, u32) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const PaintFXBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *PaintFXBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The pixels' colours changed in place, as `adjust` says.
    pub fn AdjustColours(self: *PaintFXBase, pixels: *const paintfx.Pixels, adjust: *const paintfx.Adjust) void {
        return libraries.call(self, LVO.AdjustColours, Fn.AdjustColours, .{ pixels, adjust });
    }

    /// The pixels blurred over `radius` pixels into `into`, `from`'s size.
    pub fn BlurPixels(self: *PaintFXBase, from: *const paintfx.Pixels, into: *const paintfx.Pixels, radius: u32) i32 {
        return libraries.call(self, LVO.BlurPixels, Fn.BlurPixels, .{ from, into, radius });
    }

    /// The pixels sharpened: their difference from a blur over `radius` added, `amount` percent.
    pub fn SharpenPixels(self: *PaintFXBase, from: *const paintfx.Pixels, into: *const paintfx.Pixels, amount: u32, radius: u32) i32 {
        return libraries.call(self, LVO.SharpenPixels, Fn.SharpenPixels, .{ from, into, amount, radius });
    }

    /// The pixels scaled to `into`'s size (PFXSCALE_*).
    pub fn ScalePixels(self: *PaintFXBase, from: *const paintfx.Pixels, into: *const paintfx.Pixels, how: u32) i32 {
        return libraries.call(self, LVO.ScalePixels, Fn.ScalePixels, .{ from, into, how });
    }

    /// Each pixel of `into` taken from where `matrix` puts it in `from` (PFXSCALE_*).
    pub fn TransformPixels(self: *PaintFXBase, from: *const paintfx.Pixels, into: *const paintfx.Pixels, matrix: *const paintfx.Matrix, how: u32) void {
        return libraries.call(self, LVO.TransformPixels, Fn.TransformPixels, .{ from, into, matrix, how });
    }
};
